app.use((err, req, res, next) => {
  // Log full detail server-side only
  console.error(err);
  const status = err.status || 500;
  res.status(status).json({
    error: status === 500 ? 'Internal Server Error' : err.message,
  });
});
```

Also add a 404 handler before it so unknown paths return JSON instead of Express's default HTML:

```js
app.use((req, res) => res.status(404).json({ error: 'Not Found' }));
```

And handle process-level failures so the app fails loudly instead of silently:

```js
process.on('unhandledRejection', (reason) => { console.error(reason); process.exit(1); });
process.on('uncaughtException',  (err)    => { console.error(err);    process.exit(1); });
```

## 2. No input validation

Neither route currently takes user input, but as soon as you add `/users/:id`, query filters, or a `POST /users`, you'll need validation. Adopt a schema validator now so the pattern is in place.

**Recommendation:** Use `zod` or `joi` and validate at the boundary.

```js
const { z } = require('zod');

const IdParam = z.object({ id: z.coerce.number().int().positive() });

app.get('/users/:id', (req, res, next) => {
  const parsed = IdParam.safeParse(req.params);
  if (!parsed.success) {
