const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { param, validationResult } = require('express-validator');

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// --- Security & parsing middleware ---
app.use(helmet());                                      // secure headers
app.use(express.json({ limit: '10kb' }));               // cap body size
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// --- Rate limiting ---
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,   // 15 minutes
  max: 100,                    // 100 requests per IP per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/users', apiLimiter);

// --- Helper: wrap async handlers so errors hit the error middleware ---
const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

// --- Validation result handler ---
const handleValidation = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ error: 'Invalid input', details: errors.array() });
  }
  next();
};

// --- Routes ---
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', asyncHandler(async (req, res) => {
  // In real code: fetch from DB with parameterized query
  res.json([
    { id: 1, name: 'Alice' },   // omit email unless caller is authorized
    { id: 2, name: 'Bob' },
  ]);
}));

// Example of validated route
app.get(
  '/users/:id',
  param('id').isInt({ min: 1 }).toInt(),
  handleValidation,
  asyncHandler(async (req, res) => {
    const { id } = req.params;
    // Fetch from DB using parameterized query — never string concat
    res.json({ id, name: 'Alice' });
  })
);

// --- 404 handler ---
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// --- Centralized error handler (must have 4 args) ---
app.use((err, req, res, next) => {
  // Log full error server-side only
  console.error('[error]', { message: err.message, stack: err.stack, path: req.path });

  const status = err.status || 500;
  res.status(status).json({
    error: status === 500 ? 'Internal server error' : err.message,
    // Never expose stack traces in production
    ...(NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// --- Start server with graceful shutdown ---
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

const shutdown = (signal) => {
  console.log(`${signal} received, shutting down gracefully`);
  server.close(() => process.exit(0));
  // Force exit if not closed in 10s
  setTimeout(() => process.exit(1), 10000).unref();
};
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// Surface unhandled rejections instead of swallowing them
process.on('unhandledRejection', (reason) => {
  console.error('[unhandledRejection]', reason);
});

module.exports = app;
```

